const written = [];

function generate(schematic, name, options = {}) {
  const files =
    schematic === "service"
      ? [`src/services/${name}/${name}.service.ts`, `src/services/${name}/index.ts`]
      : [`src/repositories/${name}.repository.ts`, "src/repositories/index.ts"];
  if (options.dryRun !== true) written.push(...files);
  return files;
}

console.log(generate("repository", "task", { dryRun: true }));
console.log(written.length);
generate("service", "task");
console.log(written);
